import { html, css, nothing } from 'lit';
import { customElement, property, state } from 'lit/decorators.js';
import { ifDefined } from 'lit/directives/if-defined.js';
import { UUICardElement } from "@umbraco-cms/backoffice/external/uui";

// import {
//   UUISymbolFolderElement,
//   UUISymbolFileElement,
//   UUISymbolExpandElement
// } from "@umbraco-cms/backoffice/external/uui";

/*
* base on UUICardMediaElement
  src/components/card-media/card-media.element.ts of Umbraco.UI repository
*/
const elementName = 'wysiwg-card-media';
@customElement(elementName)
export class WysiwgCardMediaElement extends UUICardElement {
  /**
   * Media name
   * @type {string}
   * @attr name
   * @default ''
   */
  @property({ type: String })
  name = '';

  /**
   * Media detail
   * @type {string}
   * @attr detail
   * @default ''
   */
  @property({ type: String })
  detail?: string;

  /**
   * Media file extension, without "."
   * @type {string}
   * @attr file-ext
   * @default ''
   */
  @property({ type: String, attribute: 'file-ext' })
  fileExt = '';

  @state()
  private _iconSlotHasContent = false;

  private _iconSlotChanged = (e: Event): void => {
    this._iconSlotHasContent =
      (e.target as HTMLSlotElement).assignedNodes({ flatten: true }).length > 0;
  };

  @state()
  protected hasPreview = false;

  private queryPreviews(e: Event): void {
    this.hasPreview =
      (e.composedPath()[0] as HTMLSlotElement).assignedElements({
        flatten: true,
      }).length > 0;
  }

  protected renderMedia() {
    if (this.hasPreview === true) return '';

    if (this.fileExt === '') {
      return html`<uui-symbol-folder id="entity-symbol"></uui-symbol-folder>`;
    }

    return html`<uui-symbol-file
      id="entity-symbol"
      type="${this.fileExt}"></uui-symbol-file>`;
  }

  #renderButton() {
    const tabIndex = !this.disabled ? (this.selectOnly ? -1 : 0) : undefined;
    return html`
      <button
        id="open-part"
        tabindex=${ifDefined(tabIndex)}
        @click=${this.handleOpenClick}
        @keydown=${this.handleOpenKeydown}>
        ${this.#renderContent()}
      </button>
    `;
  }

  #renderLink() {
    const tabIndex = !this.disabled ? (this.selectOnly ? -1 : 0) : undefined;
    const rel = this.target === '_blank' ? 'noopener noreferrer' : undefined;
    return html`
      <a
        id="open-part"
        tabindex=${ifDefined(tabIndex)}
        href=${ifDefined(!this.disabled ? this.href : undefined)}
        target=${ifDefined(this.target || undefined)}
        rel=${ifDefined(this.rel || rel)}>
        ${this.#renderContent()}
      </a>
    `;
  }

  #renderContent() {
    return html`
      <div id="content" class="uui-text">
        <span id="name" title="${this.name}">
          ${this.hasChildren
        ? html`<uui-symbol-expand aria-hidden="true"></uui-symbol-expand>`
        : nothing}
          <slot
            name="icon"
            id="icon"
            style=${this._iconSlotHasContent ? '' : 'display: none;'}
            @slotchange=${this._iconSlotChanged}></slot
          ><span class="label">${this.name}</span>
        </span>
        <small id="detail">${this.detail}<slot name="detail"></slot></small>
      </div>
    `;
  }

  public render() {
    const rVal = html` ${this.renderMedia()}
      <slot @slotchange=${this.queryPreviews}></slot>
      ${this.href ? this.#renderLink() : this.#renderButton()}
      <!-- Select border must be right after .open-part -->
      <div id="select-border"></div>
      ${this.selectable ? this.renderCheckbox() : nothing}
      <slot name="tag"></slot>
      <slot name="actions"></slot>`;

    return rVal;
  }

  static override readonly styles = [
    ...UUICardElement.styles,
    css`
      #entity-symbol {
        align-self: center;
        width: 60%;
        margin-bottom: var(--uui-size-layout-1);
        padding: var(--uui-size-space-6);
      }

      slot:not([name]) {
        display: block;
        width: 100%;
        margin: calc(var(--uui-border-radius-2) - 1px);
        margin-bottom: 38px;
        overflow: visible;
      }

      slot:not([name])::slotted(*) {
        align-self: center;
        object-fit: cover;
        width: 100%;
        pointer-events: none;
      }

      slot[name='tag'] {
        position: absolute;
        bottom: var(--uui-size-2);
        right: var(--uui-size-4);
        display: flex;
        justify-content: right;
        z-index: 2;
      }

      slot[name='actions'] {
        position: absolute;
        top: var(--uui-size-space-3);
        right: var(--uui-size-space-3);
        display: flex;
        justify-content: right;
        z-index: 2;
        opacity: 0;
        transition: opacity 120ms;
      }
      :host(:focus) slot[name='actions'],
      :host(:focus-within) slot[name='actions'],
      :host(:hover) slot[name='actions'] {
        opacity: 1;
      }

      #open-part {
        position: absolute;
        z-index: 1;
        inset: 0;
        margin-bottom: 0;
        color: var(--uui-color-interactive);
        border: none;
        cursor: pointer;
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
      }

      :host([disabled]) #open-part {
        pointer-events: none;
        color: var(--uui-color-contrast-disabled);
      }

      #open-part:hover {
        color: var(--uui-color-interactive-emphasis);
      }
      #open-part:hover #name {
        text-decoration: underline;
      }

      #open-part #name {
        display: flex;
        align-items: center;
        gap: var(--uui-size-space-1);
      }

      #open-part #name .label {
        display: -webkit-box;
        -webkit-line-clamp: 1;
        -webkit-box-orient: vertical;
        overflow: hidden;
        text-overflow: ellipsis;
        overflow-wrap: anywhere;
      }

      :host([image]:not([image=''])) #open-part {
        transition: opacity 0.5s 0.5s;
        opacity: 0;
      }

      #content {
        position: relative;
        display: flex;
        flex-direction: column;
        font-family: inherit;
        box-sizing: border-box;
        text-align: left;
        word-break: break-word;
        padding-top: var(--uui-size-space-3);
      }

      #content::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        border-top: 1px solid var(--uui-color-divider);
        border-radius: 0 0 calc(var(--uui-border-radius-2) - 1px)
          calc(var(--uui-border-radius-2) - 1px);
        background-color: var(--uui-color-surface);
        pointer-events: none;
        opacity: 0.96;
      }

      #icon {
        display: inline-flex;
        margin-right: var(--uui-size-1);
      }

      #detail {
        opacity: 0.6;
      }

      :host(
          [image]:not([image='']):hover,
          [image]:not([image='']):focus,
          [image]:not([image='']):focus-within,
          [selected][image]:not([image='']),
          [error][image]:not([image=''])
        )
        #open-part {
        opacity: 1;
        transition-duration: 120ms;
        transition-delay: 0s;
      }

      :host([selectable]) #open-part {
        inset: var(--uui-size-space-3) var(--uui-size-space-4);
      }
      :host(:not([selectable])) #content {
        padding: var(--uui-size-space-3) var(--uui-size-space-4);
      }
      :host([selectable]) #content::before {
        inset: calc(var(--uui-size-space-3) * -1)
          calc(var(--uui-size-space-4) * -1);
        top: 0;
      }

      :host([active]) {
        background-color: var(--uui-color-surface);
      }

      :host([active]) #content::before {
        background-color: var(--uui-color-current);
        bottom: -1px;
      }

      /*
      #info-icon {
        margin-right: var(--uui-size-2);
        display: flex;
        height: var(--uui-size-8);
      }
      */
    `,
  ];
}

export default WysiwgCardMediaElement;

declare global {
  interface HTMLElementTagNameMap {
    'wysiwg-card-media': WysiwgCardMediaElement;
  }

}
